class TestCollectMetrics:
    """Validation of the metric collection function."""

    def test_returns_dict_with_all_requested_metric_types(self, mock_metric_data):
        """Verify that all requested metric types are present in the result."""
        with patch("SystemMetricsSkill.collect_metric_data", side_effect=lambda sid, mt: mock_metric_data[mt]):
            result = collect_metrics("system-123", ["cpu_usage", "memory_usage"])

        assert isinstance(result, dict)
        assert set(result.keys()) == {"cpu_usage", "memory_usage"}
        assert result["cpu_usage"] == mock_metric_data["cpu_usage"]

    def test_empty_metric_types_returns_empty_dict(self):
        """Edge case: empty metric type list should yield empty dict."""
        with patch("SystemMetricsSkill.collect_metric_data") as mock_collector:
            result = collect_metrics("system-123", [])

        assert result == {}
        mock_collector.assert_not_called()

    def test_single_metric_type(self, mock_metric_data):
        """Verify behavior with a single metric type."""
        with patch("SystemMetricsSkill.collect_metric_data", return_value=mock_metric_data["cpu_usage"]):
            result = collect_metrics("system-123", ["cpu_usage"])

        assert len(result) == 1
        assert "cpu_usage" in result

    def test_propagates_exception_from_metric_collector(self):
        """Error path: exceptions from the underlying collector must propagate."""
        with patch("SystemMetricsSkill.collect_metric_data", side_effect=RuntimeError("API failure")):
            with pytest.raises(RuntimeError, match="API failure"):
                collect_metrics("system-123", ["cpu_usage"])

    def test_metric_types_must_be_iterable(self):
        """Validation: non-iterable input should raise TypeError."""
        with pytest.raises(TypeError):
            collect_metrics("system-123", None)


